-- GDPR CONTENT PACK (2026-08-13) — real Stage 1 question bank for the 'gdpr' framework,
-- replacing the 3-orphan-question stub left by the original Excel loader.
-- Source: docs/extracted/GDPR Assessment App/GDPR_Audit_Tool_v4.html (77 questions,
-- GDPR EU & UK + Data (Use and Access) Act 2025 + ISO/IEC 27701:2019, 6 sections).
--
-- Pure content: one content_pack row + 77 assessment_questions rows. Zero schema change —
-- the content-driven acceptance test, again. Scoring rides the existing engine unchanged:
-- the prototype scores fully=2 / partial=1 / non-compliant=0, N/A excluded from the
-- denominator, rating >=75% satisfactory / >=50% requires_improvement / else
-- significant_gaps — exactly what calculate_assessment_score() already does.
--
-- Orphan note: staging carries 3 pre-existing 'gdpr' questions (uid style S1_Q1) inserted
-- by load_questions_from_excel.py and deactivated by 20260806000002 (active = FALSE).
-- They are left untouched here: inactive rows never render (the questions API filters
-- active = TRUE) and may carry responses we cannot check from a migration. The spine
-- backfill (20260810000002) may already have created a global (gdpr, v1) 'Seed pack' for
-- them on staging — the ON CONFLICT below reuses that pack and the UPDATE renames it, so
-- this migration is correct both on staging (pack exists) and on a fresh dev DB (it does
-- not). New uids are namespaced 'gdpr.S1Q1' — no collision with the orphans.

BEGIN;

-- global content pack for the framework ('gdpr' already registered in frameworks, track_kind='privacy')
INSERT INTO public.content_packs (practice_id, framework_key, version, label, status)
  VALUES (NULL, 'gdpr', 1, 'GDPR (EU & UK) + DUAA 2025 + ISO 27701', 'published')
  ON CONFLICT (framework_key, version) WHERE practice_id IS NULL DO NOTHING;

-- if the spine backfill already created the pack as 'Seed pack', give it its real label
UPDATE public.content_packs
   SET label = 'GDPR (EU & UK) + DUAA 2025 + ISO 27701', status = 'published'
 WHERE framework_key = 'gdpr' AND version = 1 AND practice_id IS NULL;

-- ---------- Stage 1: assessment questions (77, six sections) ----------
INSERT INTO public.assessment_questions
  (framework, content_pack_id, section_id, section_name, subsection, question_number,
   question, why_matters, regulatory_ref, risk, evidence_req, remediation, uid)
SELECT 'gdpr', cp.id, x.section_id, x.section_name, x.subsection, x.qn,
       x.question, x.why, x.ref, x.risk, x.evidence, x.remediation, x.uid
FROM (SELECT id FROM public.content_packs
      WHERE framework_key = 'gdpr' AND version = 1 AND practice_id IS NULL) cp,
(VALUES
  (1,'Procedural Issues & Awareness','GOVERNANCE & ACCOUNTABILITY',1,'Has the organisation formally adopted a Data Protection / Privacy Management System (DPMS/PIMS) with board-level ownership, a documented scope, and accountability assigned to a named senior leader?','GDPR Art. 5(2) accountability demands that the controller can demonstrate compliance. ISO 27701 cl.5.1 requires top management to demonstrate leadership and commitment to the PIMS. The DUAA 2025 reinforces this with senior responsible officer (SRO) obligations for data intermediaries.','GDPR Art. 5(2), 24; DUAA 2025 s.84–86 (SRO obligations); ICO Accountability Framework | ISO 27701 cl.5.1 (Leadership & commitment), cl.5.2.1 (Context of organisation), cl.5.4 (Leadership)','Critical','Board-approved DPMS/PIMS scope document; governance charter naming SRO; board resolution adopting the PIMS; management review schedule; ISO 27701 gap assessment or certification.','Define and document the PIMS scope per ISO 27701 cl.5.2. Identify the SRO and obtain board endorsement. Map the PIMS to GDPR Art. 5 principles and DUAA 2025 obligations. Schedule annual management reviews (ISO 27701 cl.9.3).','gdpr.S1Q1'),
  (1,'Procedural Issues & Awareness','GOVERNANCE & ACCOUNTABILITY',2,'Has a Data Protection Officer (DPO) been appointed where required under GDPR Article 37, with documented responsibilities, adequate resources, and contact details published to the supervisory authority and data subjects?','GDPR Arts. 37–39 mandate a DPO for specific processing scenarios. ISO 27701 cl.5.3.2 requires roles, responsibilities, and authorities to be assigned and communicated. A conflicted or under-resourced DPO provides no real protection and is itself an enforcement risk.','GDPR Art. 37–39, 37(7); ICO DPO guidance | ISO 27701 cl.5.3.2 (Organisational roles, responsibilities & authorities)','Critical','DPO appointment letter confirming independence; DPO contact details on website and privacy notices; notification to ICO/supervisory authority; DPO job description with allocated resources; evidence of no conflicting management role.','Conduct mandatory appointment assessment. Appoint a DPO with sufficient expertise and resources. Publish contact details and notify the ICO. Review annually. Ensure DPO has direct access to the board.','gdpr.S1Q2'),
  (1,'Procedural Issues & Awareness','GOVERNANCE & ACCOUNTABILITY',3,'Has the organisation conducted and documented a formal context-of-organisation assessment identifying all internal and external stakeholders with privacy interests, including regulators, processors, joint controllers, and DUAA 2025 data intermediaries?','GDPR Art. 24 requires controls calibrated to the ''nature, scope, context and purposes'' of processing. ISO 27701 cl.5.2.1–5.2.2 require understanding the organisation''s context and the needs and expectations of interested parties. DUAA 2025 introduces new stakeholder categories (data intermediaries, data trustees, access bodies).','GDPR Art. 24; DUAA 2025 s.66–83 | ISO 27701 cl.5.2.1 (Understanding the organisation), cl.5.2.2 (Needs & expectations of interested parties)','High','Context assessment / stakeholder mapping document; risk register referencing privacy risks by stakeholder group; DUAA 2025 role assessment; update log (minimum annual).','Conduct a stakeholder and context analysis per ISO 27701 cl.5.2. Identify DUAA 2025 roles. Update governance structure accordingly. Review at least annually and following material changes.','gdpr.S1Q3'),
  (1,'Procedural Issues & Awareness','GOVERNANCE & ACCOUNTABILITY',4,'Is data protection compliance a standing agenda item at board and senior management meetings, with documented decisions, corrective actions, and formal annual management review outputs?','GDPR Art. 5(2) accountability requires demonstrable senior oversight. ISO 27701 cl.9.3 mandates a formal annual management review of the PIMS covering audit results, performance metrics, and improvement opportunities.','GDPR Art. 5(2), 24; DUAA 2025 s.84 | ISO 27701 cl.5.1 (Leadership & commitment), cl.9.3 (Management review)','High','Board/EXCO meeting agendas and minutes showing standing DP item; annual ISO 27701 management review outputs with corrective actions tracked; DPO quarterly board reports.','Add DP as a mandatory standing board item. Require DPO quarterly updates. Minute all decisions. Conduct a formal annual PIMS management review per ISO 27701 cl.9.3. Produce an annual DP report for the board.','gdpr.S1Q4'),
  (1,'Procedural Issues & Awareness','POLICIES & PROCEDURES',5,'Does the organisation maintain a current, board-approved Data Protection Policy covering all GDPR Art. 5 principles, DUAA 2025 obligations, and ISO 27701 privacy controls, with version control and an annual review cycle?','A documented, current policy is the foundation of GDPR Art. 5(2) accountability. ISO 27701 cl.5.2 and cl.6.2 require PII-related objectives to be established and documented. The DUAA 2025 imposes additional obligations on intermediaries.','GDPR Art. 5, 24; DUAA 2025 Parts 1–3 | ISO 27701 cl.5.2 (PIMS scope & objectives), cl.6.2 (PII-related objectives)','Critical','Board-approved Data Protection Policy with GDPR Art. 5 mapping; ISO 27701 control cross-reference; DUAA 2025 obligations mapping; version history; annual review log.','Update the policy to address all GDPR Art. 5 principles, DUAA 2025 obligations, and ISO 27701 privacy controls. Version-control, board-approve, and review annually.','gdpr.S1Q5'),
  (1,'Procedural Issues & Awareness','POLICIES & PROCEDURES',6,'Does the organisation maintain a Record of Processing Activities (RoPA) per GDPR Article 30 covering all processing operations (controller and processor activities), and is it kept current with ISO 27701 data inventory requirements?','GDPR Art. 30 mandates the RoPA. ISO 27701 cl.7.2.1 (controller) and cl.8.2.1 (processor) require a PII inventory and data flow mapping as the foundation for all other privacy controls. Without a current RoPA the organisation cannot demonstrate compliance with any principle.','GDPR Art. 30; DUAA 2025 s.1–25 | ISO 27701 cl.7.2.1 (PII inventory & mapping – controller), cl.8.2.1 (PII inventory – processor)','Critical','RoPA with all Art. 30 mandatory fields; ISO 27701 data inventory including data categories, flows, owners, retention periods, recipients, security measures; last review date.','Build/update RoPA with all Art. 30 fields and ISO 27701 inventory requirements. Assign data owners. Review and update at least annually and on any new processing activity.','gdpr.S1Q6'),
  (1,'Procedural Issues & Awareness','POLICIES & PROCEDURES',7,'Are all data protection policies and procedures subject to a documented review cycle (minimum annual) with version control, management sign-off, and change history retained?','GDPR Art. 5(2) requires policies to remain current. ISO 27701 cl.7.5 (Documented information) and cl.10.2 (Continual improvement) require systematic management of documented information. Outdated policies undermine demonstrable compliance.','GDPR Art. 5(2), 24 | ISO 27701 cl.7.5 (Documented information), cl.10.2 (Continual improvement)','High','Policy register with version history, review dates, and approvers; document management system; evidence of ad-hoc reviews triggered by regulatory changes (DUAA 2025 commencement) or incidents.','Establish a formal policy review calendar. Require management sign-off on each version. Retain all previous versions. Trigger ad-hoc reviews on regulatory change or material processing change.','gdpr.S1Q7'),
  (1,'Procedural Issues & Awareness','POLICIES & PROCEDURES',8,'Does the organisation issue lawful, transparent, and complete privacy notices to data subjects at the point of collection, covering all Art. 13/14 information and ISO 27701 transparency requirements?','GDPR Arts. 13–14 mandate privacy notice content. ISO 27701 cl.7.3.2 (Providing privacy notices) and cl.7.3 (Obligations to PII principals) operationalise this at a system and process level. The DUAA 2025 requires additional disclosures for recognised legitimate interests and intermediary roles.','GDPR Art. 5(1)(a), 12–14; DUAA 2025 s.68 | ISO 27701 cl.7.3 (Obligations to PII principals), cl.7.3.2 (Providing privacy notices)','Critical','Privacy notices on all data collection touchpoints; Art. 13/14 content checklist; DUAA 2025 disclosure checklist; ISO 27701 cl.7.3.2 compliance review; layered notice evidence.','Audit all collection touchpoints. Ensure notices cover all Art. 13/14 elements and ISO 27701 cl.7.3.2 requirements. Update for DUAA 2025 recognised legitimate interests where applicable. Review annually.','gdpr.S1Q8'),
  (1,'Procedural Issues & Awareness','PRIVACY RISK & IMPACT ASSESSMENTS',9,'Does the organisation conduct DPIAs for all high-risk processing activities, are they embedded as a mandatory project governance gate, and do they include ISO 27701 PII risk assessment methodology?','GDPR Art. 35 mandates DPIAs. ISO 27701 cl.6.1.2 requires a structured PII-related risk assessment process and cl.7.2.5 (Privacy by Design) requires risk assessment at design stage. The DUAA 2025 introduces new processing activities that may themselves trigger DPIA obligations.','GDPR Art. 35–36; DUAA 2025 (new processing activities); EDPB DPIA guidance | ISO 27701 cl.6.1.2 (PII-related risk assessment), cl.7.2.5 (Privacy by design & default)','Critical','DPIA policy; DPIA screening tool; completed DPIAs for current high-risk processing; DPIA register; DPO consultation records; project governance gate records confirming DPIA sign-off before go-live.','Embed DPIA as a mandatory project governance gate using a risk-tiered screening tool aligned to ISO 27701 cl.6.1.2. Consult DPO on every DPIA. Maintain a DPIA register. Consult ICO/SA for residual high-risk processing.','gdpr.S1Q9'),
  (1,'Procedural Issues & Awareness','PRIVACY RISK & IMPACT ASSESSMENTS',10,'Is Privacy by Design and by Default implemented per GDPR Art. 25 and ISO 27701, ensuring privacy controls are built into systems from the outset and only minimum data is processed by default?','GDPR Art. 25 and ISO 27701 cl.7.2.5 both require data minimisation and privacy-protective defaults to be embedded at the design stage — not retrofitted. The DUAA 2025 reinforces minimisation for data access bodies.','GDPR Art. 25; DUAA 2025 s.3–8; EDPB Guidelines 4/2019 | ISO 27701 cl.7.2.5 (Privacy by design & default)','High','Privacy by Design checklist used in IT/product development; system design specs showing privacy controls; data minimisation justification log; default settings review; post-implementation privacy review records.','Implement a Privacy by Design checklist per ISO 27701 cl.7.2.5 in all IT/product governance. Require DPO review of new designs. Enforce opt-in defaults. Conduct post-implementation privacy reviews.','gdpr.S1Q10'),
  (1,'Procedural Issues & Awareness','STAFF TRAINING & AWARENESS',11,'Is there a documented, role-based data protection training programme covering GDPR, DUAA 2025, and ISO 27701 obligations, with completion tracked and refresher training at least annually?','GDPR Art. 39(1)(b) and ISO 27701 cl.7.4 (Awareness) and cl.6.3 (PII handling training) require a structured, evidenced awareness programme. The DUAA 2025 introduces new obligations for staff handling intermediary and smart data roles.','GDPR Art. 39(1)(b), 5(2); DUAA 2025 | ISO 27701 cl.7.4 (Awareness), cl.6.3 (Awareness & training for PII handling)','Critical','Training curriculum covering GDPR, DUAA 2025, ISO 27701; LMS completion records by employee; role-differentiated modules; annual refresher schedule; non-completion escalation records.','Develop role-differentiated training modules (general staff, IT, legal, marketing, HR, intermediary roles). Mandate completion within 30 days of onboarding and annually. Include DUAA 2025 smart data obligations. Track via LMS. Escalate non-completions.','gdpr.S1Q11'),
  (1,'Procedural Issues & Awareness','STAFF TRAINING & AWARENESS',12,'Are staff who handle personal data required to sign a confidentiality agreement that includes data protection obligations and post-employment restrictions?','GDPR Art. 32(4) requires that persons with access to personal data must not process it without instruction. ISO 27701 cl.6.6 (Confidentiality or non-disclosure agreements) requires formal confidentiality commitments from personnel. Post-employment restrictions protect against ongoing risk.','GDPR Art. 32(4), 28(3)(b) | ISO 27701 cl.6.6 (Confidentiality or NDA agreements)','High','Signed confidentiality agreements referencing personal data and GDPR; employment contracts with post-termination data protection clauses; offboarding checklist confirming return/destruction of data assets.','Include a data protection and post-termination confidentiality clause in all employment contracts. Require confidentiality agreements at onboarding. Confirm during offboarding that data assets are returned or destroyed.','gdpr.S1Q12'),
  (1,'Procedural Issues & Awareness','STAFF TRAINING & AWARENESS',13,'Are staff aware of how to recognise and immediately report a personal data breach to the DPO, with the 72-hour notification obligation clearly understood?','The GDPR Art. 33 72-hour clock starts when any staff member becomes aware of a breach — not when it reaches the DPO. ISO 27701 cl.6.13.1 requires documented responsibilities and procedures for PII breach management at every organisational level. The DUAA 2025 adds notification obligations for data intermediaries.','GDPR Art. 33–34; DUAA 2025 s.84; EDPB Guidelines 01/2021 | ISO 27701 cl.6.13.1 (Responsibilities & procedures for PII breach management)','Critical','Breach reporting procedure; staff training records on breach recognition; breach reporting channel details; annual tabletop exercise reports; internal breach register.','Publish a breach reporting procedure in the staff handbook and intranet. Include breach recognition and 72-hour obligation in all GDPR/ISO 27701 training. Operate a dedicated breach reporting channel. Conduct annual tabletop exercises.','gdpr.S1Q13'),
  (2,'Lawful Processing of Personal Data','PROCESSING LIMITATION & LAWFUL BASIS',1,'Has the organisation identified, documented, and mapped a specific GDPR Art. 6 lawful basis (and Art. 9 condition for special category data) for each processing activity in the RoPA, including DUAA 2025 recognised legitimate interests?','Processing without a lawful basis is unlawful. ISO 27701 cl.7.2.2 (Determining lawful basis) and cl.7.2.3 require the lawful basis to be documented and linked to the purpose for each processing activity. The DUAA 2025 s.57–65 introduce pre-approved recognised legitimate interests that must still be documented.','GDPR Art. 6, 9; DUAA 2025 s.57–65 (recognised legitimate interests) | ISO 27701 cl.7.2.2 (Determining lawful basis), cl.7.2.3 (Determining when & how consent is obtained)','Critical','RoPA with lawful basis column per processing activity; LIAs for Art. 6(1)(f) reliance; DUAA 2025 recognised LI assessments; Art. 9 conditions documented; consent records; contractual necessity justification.','Review RoPA and document a lawful basis for every activity. Conduct LIAs for legitimate interest reliance. Assess applicability of DUAA 2025 recognised LI. Document Art. 9 conditions for special category data. Reflect basis in privacy notices.','gdpr.S2Q1'),
  (2,'Lawful Processing of Personal Data','PROCESSING LIMITATION & LAWFUL BASIS',2,'Where consent is the lawful basis, is it freely given, specific, informed, unambiguous, captured per data subject and purpose, recorded with timestamp and wording version, and free of pre-ticked boxes or bundled consent?','GDPR Art. 4(11) and Art. 7 set strict consent conditions. ISO 27701 cl.7.2.3 and cl.7.3.4 operationalise consent capture and recording at a technical and process level. Invalid consent renders processing unlawful.','GDPR Art. 4(11), 7; Recital 32, 43; EDPB Guidelines 05/2020 | ISO 27701 cl.7.2.3 (When & how consent is obtained), cl.7.3.4 (Providing mechanisms to obtain consent)','Critical','Consent management system records: timestamp, wording version, channel, purpose per data subject; opt-in forms with no pre-ticked boxes; consent withdrawal records; quarterly consent audit trail.','Implement a consent management platform capturing consent per data subject, purpose, channel, with timestamp and wording version. Audit all mechanisms. Remove pre-ticked boxes and bundled consent. Conduct quarterly audits.','gdpr.S2Q2'),
  (2,'Lawful Processing of Personal Data','PROCESSING LIMITATION & LAWFUL BASIS',3,'Is there a documented process for withdrawing consent that is as easy as giving it, with withdrawal actioned within 5 business days and processing ceasing immediately where consent was the sole basis?','GDPR Art. 7(3) requires withdrawal to be as easy as consent. ISO 27701 cl.7.3.5 requires a mechanism to modify or withdraw consent. Failure to action withdrawals is a continuing breach. Suppression must be immediate.','GDPR Art. 7(3); EDPB Guidelines 05/2020 | ISO 27701 cl.7.3.5 (Providing mechanism to modify or withdraw consent)','High','Consent withdrawal procedure; withdrawal request log with action dates; suppression list updates; evidence of processing cessation; confirmation to data subject.','Implement a simple withdrawal mechanism (one-click, email, telephone). Define 5 business day SLA. Cease processing immediately on withdrawal. Confirm cessation to the data subject in writing.','gdpr.S2Q3'),
  (2,'Lawful Processing of Personal Data','PROCESSING LIMITATION & LAWFUL BASIS',4,'Has the organisation identified all special category (Art. 9) and criminal conviction (Art. 10) data and documented a specific condition and safeguard for each processing activity, with heightened ISO 27701 security controls applied?','Processing special category data without both an Art. 6 and Art. 9 condition is unlawful. ISO 27701 cl.7.2.8 requires additional safeguards for sensitive PII. These are the highest-risk data categories under GDPR and attract enhanced regulatory scrutiny.','GDPR Art. 9–10; Schedule 1 UK GDPR; EDPB Guidelines 08/2022 | ISO 27701 cl.7.2.8 (Processing of sensitive PII)','Critical','Special category data register; Art. 9 condition and safeguard documented per activity; Sch. 1 UK GDPR conditions; DPIA for high-risk special category processing; enhanced access controls; encryption evidence.','Identify all special category and criminal conviction data. Document Art. 9 conditions and safeguards. Apply ISO 27701 cl.7.2.8 controls: explicit consent or statutory authority, restricted access, encryption, enhanced retention. Conduct DPIAs.','gdpr.S2Q4'),
  (2,'Lawful Processing of Personal Data','PURPOSE SPECIFICATION',5,'Are processing purposes defined with sufficient specificity, documented in the RoPA per ISO 27701 cl.7.2.1, and consistently communicated to data subjects in privacy notices?','GDPR Art. 5(1)(b) requires purposes to be ''specified, explicit and legitimate''. ISO 27701 cl.7.2.1 (RoPA) and cl.7.3.2 (privacy notices) require purposes to be documented and communicated. Vague or bundled purposes breach the purpose limitation principle.','GDPR Art. 5(1)(b), 13–14; DUAA 2025 s.3 | ISO 27701 cl.7.2.1 (RoPA & data inventory), cl.7.3.2 (Providing privacy notices)','Critical','RoPA with granular purpose descriptions; corresponding privacy notices with consistent purpose language; internal purpose definition policy; evidence of no generic or open-ended purpose statements.','Ensure all purposes are stated at a granular, specific level in the RoPA and privacy notices. Avoid bundled statements. Update purposes on any processing change.','gdpr.S2Q5'),
  (2,'Lawful Processing of Personal Data','PURPOSE SPECIFICATION',6,'Is personal data used strictly for the purpose for which it was collected, and is any further processing assessed for compatibility per GDPR Art. 6(4) and ISO 27701 cl.7.2.6?','GDPR Art. 5(1)(b) and Art. 6(4) restrict further processing. ISO 27701 cl.7.2.6 (PII processing for specified purpose only) requires technical and organisational controls to enforce purpose limitation. Incompatible further processing is a direct breach.','GDPR Art. 5(1)(b), 6(4); DUAA 2025 s.3–8 | ISO 27701 cl.7.2.6 (PII processing for specified purpose only)','High','Further processing compatibility assessment records; DPO approval for secondary use; updated privacy notices; audit logs confirming purpose adherence.','Implement a further processing compatibility test. Require DPO approval before secondary use. Where incompatible, obtain a new lawful basis and update the privacy notice.','gdpr.S2Q6'),
  (2,'Lawful Processing of Personal Data','PURPOSE SPECIFICATION',7,'Does the organisation have a documented procedure for third-party and law enforcement disclosure requests, with a disclosure log maintained and DPO/legal review required before any disclosure?','GDPR requires a legal basis for every disclosure. ISO 27701 cl.7.2.7 (Disclosures to third parties) requires documented procedures and records for all disclosures. Unreviewed disclosures breach accountability. DUAA 2025 introduces new data sharing obligations.','GDPR Art. 5(2), 6; DUAA 2025 s.12–25 | ISO 27701 cl.7.2.7 (Disclosures to third parties)','High','Third-party disclosure procedure; disclosure log (date, requester, legal basis, data disclosed, DPO approval); legal hold register; law enforcement request log.','Develop a Third-Party Disclosure Procedure requiring DPO or legal review before any disclosure. Maintain a disclosure log. Require law enforcement requests to cite statutory authority. Review disclosures monthly.','gdpr.S2Q7'),
  (2,'Lawful Processing of Personal Data','DATA MINIMISATION & QUALITY',8,'Are data collection forms, systems, and processes reviewed regularly to ensure only the minimum personal data necessary is collected, per GDPR Art. 5(1)(c) and ISO 27701 cl.7.2.5 Privacy by Design?','GDPR Art. 5(1)(c) requires data to be ''adequate, relevant and limited to what is necessary''. ISO 27701 cl.7.2.5 (Privacy by Design) operationalises minimisation at system and process level. Excessive collection is a common enforcement focus.','GDPR Art. 5(1)(c); DUAA 2025 s.3 | ISO 27701 cl.7.2.5 (Privacy by design – data minimisation)','High','Form/field justification log; data minimisation review records; DPIA outputs referencing minimisation; records of fields removed following review.','Conduct annual minimisation audits. Require field-level justification for each data item. Remove unjustified fields. Include minimisation assessment in all DPIAs.','gdpr.S2Q8'),
  (2,'Lawful Processing of Personal Data','DATA MINIMISATION & QUALITY',9,'Does the organisation have documented procedures to ensure the accuracy and currency of personal data, including an ISO 27701 cl.7.4.3 process for handling inaccurate or incomplete PII?','GDPR Art. 5(1)(d) and Art. 16 (right to rectification) require data to be accurate and kept up to date. ISO 27701 cl.7.4.3 specifically addresses handling inaccurate or incomplete PII. Inaccurate data causes harm and generates liability, particularly for automated decision-making.','GDPR Art. 5(1)(d), 16; DUAA 2025 s.46–55 | ISO 27701 cl.7.4.3 (Inaccurate or incomplete PII)','Medium','Data accuracy procedure; annual data refresh communications; CRM/system data quality reports; correction request log showing corrections within one month; notifications to third-party recipients.','Implement annual data quality reviews. Send verification communications to data subjects. Maintain a correction request log and resolve within one month. Notify third parties of corrections.','gdpr.S2Q9'),
  (2,'Lawful Processing of Personal Data','INTERNATIONAL DATA TRANSFERS',10,'Has the organisation identified all transfers of personal data to third countries, including cloud providers and SaaS platforms, and documented each in the RoPA and international transfer register per ISO 27701 cl.7.5.1?','GDPR Chapter V (Arts. 44–49) restricts transfers to third countries. ISO 27701 cl.7.5.1 (Basis for PII transfer between jurisdictions) requires documented transfer mechanisms for every transfer. Unidentified transfers cannot be made compliant.','GDPR Art. 44–49; DUAA 2025; UK GDPR Chapter V | ISO 27701 cl.7.5.1 (Basis for PII transfer between jurisdictions)','High','International transfer register (recipient country, data categories, transfer mechanism, adequacy status); cloud provider list with data location; data flow diagrams; RoPA transfer entries.','Conduct a transfer mapping exercise. Document all transfers in the RoPA and transfer register. Update whenever a new vendor or group entity is onboarded.','gdpr.S2Q10'),
  (2,'Lawful Processing of Personal Data','INTERNATIONAL DATA TRANSFERS',11,'For each international transfer, has a lawful transfer mechanism been implemented and documented (adequacy, SCCs/IDTA, BCRs, derogations), accompanied by a Transfer Impact Assessment where required?','GDPR Art. 44 prohibits transfers without a valid mechanism. Post-Schrems II, SCC reliance requires a TIA. The UK uses its IDTA/Addendum. ISO 27701 cl.7.5.1–7.5.2 require documentation of the countries and organisations to which PII may be transferred and the applicable safeguards.','GDPR Art. 44–46, 49; UK GDPR Chapter V; ICO IDTA; SCCs (2021/914); EDPB Recommendations 01/2020 | ISO 27701 cl.7.5.1, cl.7.5.2 (Countries & organisations to which PII may be transferred)','Critical','TIAs per destination country; signed EU SCCs or UK IDTA/Addendum with each recipient; adequacy decision reliance documented; BCR approval (if applicable); Art. 49 derogation assessments.','Determine adequacy status for each destination. Where no adequacy exists, implement EU SCCs or UK IDTA/Addendum with a TIA. Review TIAs annually or on material change.','gdpr.S2Q11'),
  (2,'Lawful Processing of Personal Data','PROCESSOR & SUB-PROCESSOR MANAGEMENT',12,'Does the organisation maintain a processor register, and is a GDPR Art. 28 / ISO 27701 compliant written DPA in place with each processor before processing commences?','GDPR Art. 28 mandates a written processor contract. ISO 27701 cl.7.2.7, cl.6.12 (Supplier relationships), and cl.8.5 (Operator/processor obligations) require documented supplier governance. Processing by a processor without a compliant contract creates direct controller liability.','GDPR Art. 28; DUAA 2025 s.66–83; EDPB Guidelines 07/2020 | ISO 27701 cl.7.2.7 (Disclosures to third parties), cl.6.12 (Supplier relationships), cl.8.5 (Processor obligations)','Critical','Processor register; signed DPAs with all Art. 28(3) mandatory terms; sub-processor authorisation records; DUAA 2025 intermediary agreements; processor onboarding checklist.','Identify all processors. Execute GDPR Art. 28 / ISO 27701-compliant DPAs before any data is shared. Obtain written authorisation for sub-processors. Review DPAs annually.','gdpr.S2Q12'),
  (2,'Lawful Processing of Personal Data','PROCESSOR & SUB-PROCESSOR MANAGEMENT',13,'Are processors assessed for GDPR and ISO 27701 compliance before engagement, and monitored on an ongoing basis, with audit rights exercised for high-risk processors?','GDPR Art. 28(1) requires ''sufficient guarantees''. Art. 28(3)(h) mandates audit rights. ISO 27701 cl.6.12.1 (Supplier relationships – information security in supplier relationships) requires pre-engagement assessment and ongoing monitoring. Signing a DPA alone is insufficient.','GDPR Art. 28(1), 28(3)(h); DUAA 2025 s.84 | ISO 27701 cl.6.12.1 (Supplier relationships – information security)','High','Pre-engagement processor assessment questionnaire; ISO 27001/27701 or SOC 2 certification evidence; annual processor compliance review records; audit rights exercised for high-risk processors; corrective action tracking.','Implement risk-based processor assessment before engagement. Require ISO 27001/27701 or SOC 2 for high-risk processors. Conduct annual reviews. Exercise audit rights at least every two years for high-risk processors.','gdpr.S2Q13'),
  (3,'Record Retention','DATA MAPPING & ASSET INVENTORY',1,'Has the organisation conducted a comprehensive data mapping exercise covering all personal data across structured systems, unstructured environments, and physical files, resulting in an up-to-date ISO 27701 PII inventory?','GDPR Art. 30 requires a RoPA, which depends on knowing where personal data is held. ISO 27701 cl.7.2.1 (controller) and cl.8.2.1 (processor) require a PII inventory and data flow mapping as the foundation of the PIMS. Without mapping, the RoPA is incomplete and breach responses are hampered.','GDPR Art. 30; DUAA 2025 s.1–25 | ISO 27701 cl.7.2.1 (PII inventory & mapping – controller), cl.8.2.1 (PII inventory – processor)','Critical','Data mapping report; RoPA listing systems, data categories, locations, owners, retention periods, data flows; data flow diagrams; asset discovery tool outputs; annual review log.','Conduct a data mapping exercise per ISO 27701 cl.7.2.1. Document all personal data assets in the RoPA. Assign data owners. Review and update annually and on any new system or processing activity.','gdpr.S3Q1'),
  (3,'Record Retention','DATA MAPPING & ASSET INVENTORY',2,'Does the organisation maintain an information asset register classifying personal data by sensitivity (general, special category, criminal, children''s) and mapping it to retention periods, per ISO 27701 data inventory requirements?','Data classification is the foundation of proportionate security controls and retention enforcement. ISO 27701 cl.7.2.1 requires data categories to be identified and classified. GDPR imposes higher obligations for special category and children''s data. Unclassified data cannot be protected proportionately.','GDPR Art. 9–10, 32; UK Children''s Code; DUAA 2025 | ISO 27701 cl.7.2.1 (PII inventory & mapping)','High','Information asset register with classification column; data classification policy; retention schedule cross-referenced to asset register; annual review; UK Children''s Code compliance assessment.','Implement a data classification policy (Public / Internal / Confidential / Restricted). Apply to all assets. Cross-reference to retention schedule and security controls. Review annually.','gdpr.S3Q2'),
  (3,'Record Retention','RETENTION POLICY & SCHEDULE',3,'Does the organisation have a board-approved Data Retention Policy with a retention schedule specifying retention periods for all personal data categories, referenced to the legal basis, per GDPR Art. 5(1)(e) and ISO 27701 cl.7.4.7?','GDPR Art. 5(1)(e) (storage limitation) and ISO 27701 cl.7.4.7 (Minimum necessary PII – retention) both require personal data to be retained no longer than necessary. A documented retention schedule is the operational mechanism for enforcing this. The DUAA 2025 imposes specific retention limits for smart data access.','GDPR Art. 5(1)(e), 17; DUAA 2025 s.3 | ISO 27701 cl.7.4.7 (Minimum necessary PII – retention), cl.7.5 (Documented information)','Critical','Board-approved Data Retention Policy; retention schedule (data category, period, legal basis, disposal method, owner); annual review log; statutory legislation cross-reference (Companies Act, HMRC, Employment Rights Act).','Develop a Data Retention Policy and schedule per ISO 27701 cl.7.4.7. Map each data category to its statutory or business retention period. Cross-reference applicable UK legislation. Board-approve and review annually.','gdpr.S3Q3'),
  (3,'Record Retention','RETENTION POLICY & SCHEDULE',4,'Are retention periods aligned with all applicable UK/EU sector-specific legislation, and are conflicts between statutory retention obligations formally resolved and documented?','Multiple statutory obligations may apply to the same data. Failure to apply the longest applicable period can result in both GDPR storage limitation breaches and regulatory non-compliance. ISO 27701 cl.7.4.7 requires retention to be based on documented legal requirements.','GDPR Art. 5(1)(e); Employment Rights Act 1996; Companies Act 2006; HMRC PAYE; FSMA 2000; DUAA 2025 | ISO 27701 cl.7.4.7 (Minimum necessary PII – retention)','High','Statutory retention mapping table; legal opinion for conflicting periods; retention schedule showing longer period applied with documented rationale.','Commission a statutory retention mapping exercise. Apply the longer of applicable periods. Document the rationale. Obtain legal sign-off on the completed schedule.','gdpr.S3Q4'),
  (3,'Record Retention','DELETION, DESTRUCTION & ANONYMISATION',5,'Is personal data deleted, destroyed, or anonymised as soon as the purpose has lapsed and no legal retention obligation applies, per GDPR Art. 5(1)(e) and ISO 27701 cl.7.4.7–7.4.8?','GDPR Art. 5(1)(e) and Art. 17 require deletion once data is no longer necessary. ISO 27701 cl.7.4.7 (Retention) and cl.7.4.8 (Disposal of PII) provide the operational framework for implementing deletion. Retaining data beyond its retention period is a direct breach.','GDPR Art. 5(1)(e), 17; DUAA 2025 s.3 | ISO 27701 cl.7.4.7 (Retention of PII), cl.7.4.8 (Disposal of PII)','Critical','Automated deletion/archiving rules in CRM, HR, ERP; manual deletion procedure for systems without automation; deletion logs; anonymisation procedure and sample output; deletion certificates.','Implement automated retention enforcement in all major systems. For manual systems, define quarterly deletion cycles. Maintain deletion certificates per ISO 27701 cl.7.4.8. Log all deletions.','gdpr.S3Q5'),
  (3,'Record Retention','DELETION, DESTRUCTION & ANONYMISATION',6,'Does the organisation have a documented procedure for the secure destruction of personal data in paper and electronic format, including media sanitisation standards, per ISO 27701 cl.7.4.8 and ISO 27002?','GDPR Art. 5(1)(f) requires processing to ensure appropriate security including against unlawful destruction. ISO 27701 cl.7.4.8 (Disposal of PII) and ISO 27002 cl.7.14 (Secure disposal or reuse of equipment) provide the technical standard for secure destruction. Insecure disposal constitutes a reportable breach.','GDPR Art. 5(1)(f), 32; ICO Security Outcome 8; NIST SP 800-88; BS EN 15713 | ISO 27701 cl.7.4.8 (Disposal of PII); ISO 27002 cl.7.14','High','Destruction policy; cross-cut shredder records (DIN 66399 P-4 minimum); electronic media sanitisation standard (NIST 800-88); certificates of destruction; vetted destruction vendor contracts.','Implement NIST SP 800-88 media sanitisation for electronic media. Require DIN 66399 P-4 minimum for paper. Engage vetted vendors with GDPR-compliant contracts. Retain destruction certificates.','gdpr.S3Q6'),
  (3,'Record Retention','DELETION, DESTRUCTION & ANONYMISATION',7,'Where personal data is anonymised as an alternative to deletion, is the anonymisation process documented, tested against re-identification risk, and confirmed effective per ISO 27701 and EDPB guidance?','GDPR applies to pseudonymised data but not truly anonymous data. ISO 27701 cl.7.4.8 addresses disposal of PII, including anonymisation. EDPB Opinion 05/2014 warns that re-identification risk must be assessed against all reasonably available auxiliary data, including DUAA 2025 data-sharing outputs.','GDPR Recital 26; EDPB Opinion 05/2014; ICO Anonymisation code | ISO 27701 cl.7.4.8 (Disposal of PII)','High','Anonymisation methodology documentation; re-identification risk assessment including auxiliary data; k-anonymity or equivalent testing results; annual review of re-identification risk; classification of anonymised vs. pseudonymised data.','Define an anonymisation standard appropriate to the data sensitivity. Conduct and document a re-identification risk assessment. Reassess when new data sources become available. Never treat pseudonymised data as anonymous.','gdpr.S3Q7'),
  (3,'Record Retention','ARCHIVE & DATABASE MAINTENANCE',8,'Are off-site or cloud archival storage locations included in the data inventory, subject to GDPR-compliant DPAs per ISO 27701 cl.6.12.1, and reviewed periodically to delete records past their retention period?','Personal data in archives is still subject to GDPR obligations. ISO 27701 cl.6.12.1 (Supplier relationships) requires archival storage providers to be subject to supplier governance. GDPR Art. 30 requires all recipients (including archival storage) to be documented in the RoPA.','GDPR Art. 30, 28; DUAA 2025 | ISO 27701 cl.7.4.7 (Retention), cl.6.12.1 (Supplier relationships)','Medium','Off-site/cloud storage providers in RoPA; signed DPAs with archival providers; access logs; bi-annual archive review records; destruction certificates for purged records.','Include all archival storage in the RoPA. Ensure providers have signed GDPR/ISO 27701-compliant DPAs. Conduct bi-annual archive reviews. Log all purge events.','gdpr.S3Q8'),
  (3,'Record Retention','ARCHIVE & DATABASE MAINTENANCE',9,'Are operational databases purged regularly of personal data no longer required, with purge activities logged and reported to the DPO as part of ISO 27701 continual improvement?','GDPR Art. 5(1)(e) storage limitation applies to operational systems. ISO 27701 cl.10.2 (Continual improvement) requires the effectiveness of privacy controls — including retention enforcement — to be monitored and improved. Databases accumulating personal data indefinitely are a common enforcement cause.','GDPR Art. 5(1)(e), 32 | ISO 27701 cl.7.4.7 (Retention of PII), cl.10.2 (Continual improvement)','High','Database purge schedule (minimum quarterly); purge logs with date, system, data category, record count; automated purge rule evidence; quarterly metrics report to DPO.','Establish quarterly database purge cycles. Automate where possible. Log every purge. Report metrics to DPO quarterly as part of PIMS continual improvement.','gdpr.S3Q9'),
  (3,'Record Retention','ARCHIVE & DATABASE MAINTENANCE',10,'Is there a documented procedure for personal data in backup systems, ensuring backups are subject to the retention policy and expired data is purged per ISO 27701 cl.7.4.7?','GDPR storage limitation applies to backup data. ISO 27701 cl.7.4.7 requires retention controls to apply to all copies of PII, including backups. Backup environments are frequently overlooked, creating significant compliance gaps and breach risks.','GDPR Art. 5(1)(e), 17; NIST SP 800-34 | ISO 27701 cl.7.4.7 (Minimum necessary PII – retention)','Medium','Backup retention policy aligned to data retention schedule; backup rotation/overwrite schedule; evidence of backup purge process; backup management system configuration.','Define backup data retention in the Backup Policy, aligned to the Data Retention Schedule. Implement a rotation schedule. Ensure expired data is purged from backups. Test backup purge procedures annually.','gdpr.S3Q10'),
  (4,'Security of Personal Data','INFORMATION SECURITY POLICY & GOVERNANCE',1,'Does the organisation have a board-approved Information Security Policy incorporating GDPR Art. 32 security obligations and aligned to ISO 27701 and ISO 27001, reviewed at least annually?','GDPR Art. 32 requires ''appropriate technical and organisational measures''. ISO 27701 cl.6.2 (Information security objectives and planning) requires security objectives to be established. ISO 27001 provides the security management framework within which ISO 27701 privacy controls operate.','GDPR Art. 32; DUAA 2025 s.84; ICO Security Outcomes | ISO 27701 cl.6.2 (Information security objectives); ISO 27002 cl.5.1 (Policies for information security)','Critical','Information Security Policy (board-approved, version-controlled); ISO 27001/27701 certification or gap assessment; annual review log; Art. 32 risk assessment; staff acknowledgement records.','Update the Information Security Policy to address GDPR Art. 32, ISO 27701 cl.6.2, and DUAA 2025 obligations. Board-approve and review annually. Align to ISO 27001 controls.','gdpr.S4Q1'),
  (4,'Security of Personal Data','INFORMATION SECURITY POLICY & GOVERNANCE',2,'Has the organisation conducted a formal information security risk assessment per ISO 27701 cl.6.1.2 that explicitly includes PII-related risks, with a documented risk treatment plan and residual risk acceptance?','GDPR Art. 32(1) requires security measures proportionate to the risk to individuals. ISO 27701 cl.6.1.2 (PII-related risk assessment) and cl.6.1.3 (Risk treatment) provide the structured methodology for identifying and treating privacy risks. A formal assessment is the mechanism for calibrating controls.','GDPR Art. 32, 35; DUAA 2025 s.84; EDPB Guidelines 4/2019 | ISO 27701 cl.6.1.2 (PII-related risk assessment), cl.6.1.3 (Risk treatment)','Critical','Risk assessment report with PII-specific risks; risk register; risk treatment plan; residual risk acceptance by senior management; DPIA register linked to risk assessment.','Conduct an annual ISO 27701 cl.6.1.2 risk assessment including PII risks. Develop a risk treatment plan. Document residual risk acceptance. Update following material changes in the threat landscape.','gdpr.S4Q2'),
  (4,'Security of Personal Data','PHYSICAL SECURITY',3,'Are physical access controls in place to restrict access to all areas where personal data is stored or processed, with access logs maintained per ISO 27701 cl.6.9?','GDPR Art. 32(1)(b) requires measures to ensure ongoing confidentiality and integrity. ISO 27701 cl.6.9 references physical and environmental security controls. Physical security breaches involving personal data are reportable to the ICO.','GDPR Art. 32; ICO Security Outcome 5 | ISO 27701 cl.6.9 (Physical & environmental security); ISO 27002 cl.7.2–7.4','High','Access control logs; biometric/key card records; visitor register; CCTV policy and retention records; physical security audit report.','Implement electronic access control for sensitive areas. Maintain visitor register. Review access logs monthly. Revoke access for leavers within 24 hours.','gdpr.S4Q3'),
  (4,'Security of Personal Data','PHYSICAL SECURITY',4,'Is a clear-desk and clear-screen policy enforced, with workstations configured to auto-lock after a maximum of 5 minutes of inactivity?','Physical exposure of personal data on desks or unlocked screens is a reportable breach source. ISO 27002 cl.7.7 (Clear desk and clear screen) provides the control standard. These are low-cost, high-impact preventive measures.','GDPR Art. 32; ICO Security Outcome 5 | ISO 27002 cl.7.7 (Clear desk & clear screen)','Medium','Clear-desk policy; physical security audit walkthrough records; screen lock configuration evidence (auto-lock ≤5 minutes); staff training records.','Implement and communicate a clear-desk and clear-screen policy. Configure auto-lock at maximum 5 minutes. Conduct unannounced quarterly walkthrough audits.','gdpr.S4Q4'),
  (4,'Security of Personal Data','NETWORK & SYSTEM SECURITY',5,'Is personal data encrypted at rest (AES-256 or equivalent) and in transit (TLS 1.2 minimum, TLS 1.3 preferred) per GDPR Art. 32(1)(a) and ISO 27701 cl.6.10?','GDPR Art. 32(1)(a) explicitly lists encryption as an appropriate measure. ISO 27701 cl.6.10 references cryptographic controls. Unencrypted personal data that is breached is a major aggravating factor in ICO enforcement. The DUAA 2025 requires secure transmission for data accessed through approved schemes.','GDPR Art. 32(1)(a); DUAA 2025 s.84; ICO Security Outcome 7; NCSC TLS guidance | ISO 27701 cl.6.10 (Cryptography); ISO 27002 cl.8.24 (Use of cryptography)','Critical','Encryption policy; database encryption configuration (TDE or equivalent); TLS certificate inspection reports; email encryption configuration; penetration test results; deprecated protocol disablement evidence.','Implement AES-256 for all personal data at rest. Enforce TLS 1.2 minimum (TLS 1.3 preferred) for all data in transit. Disable deprecated protocols (SSL, TLS 1.0, TLS 1.1).','gdpr.S4Q5'),
  (4,'Security of Personal Data','NETWORK & SYSTEM SECURITY',6,'Are firewalls, network segmentation, IDS/IPS, and endpoint protection deployed and actively monitored per ISO 27701 cl.6.10 and ISO 27002 network security controls?','GDPR Art. 32 requires measures ensuring ongoing confidentiality, integrity, and availability. ISO 27701 cl.6.10 references network security. Without network-level controls, personal data processed across the organisation is exposed to both internal and external threats.','GDPR Art. 32; DUAA 2025 s.84; ICO Security Outcome 6 | ISO 27002 cl.8.20 (Network security), cl.8.21 (Security of network services), cl.8.7 (Protection against malware)','Critical','Network architecture diagram; firewall rule review records; IDS/IPS alert and response logs; EDR/antivirus management console reports; quarterly security operations review.','Implement network segmentation isolating personal data systems. Deploy EDR. Conduct quarterly firewall rule reviews. Review IDS/IPS alerts daily. Produce quarterly security operations reports.','gdpr.S4Q6'),
  (4,'Security of Personal Data','NETWORK & SYSTEM SECURITY',7,'Is vulnerability management (scanning, patching, penetration testing) conducted regularly per GDPR Art. 32(1)(d) and ISO 27002 cl.8.8, with defined SLAs for remediation?','GDPR Art. 32(1)(d) explicitly requires a process for ''regularly testing, assessing and evaluating the effectiveness'' of security measures. ISO 27002 cl.8.8 (Management of technical vulnerabilities) provides the control framework. Unpatched vulnerabilities are a leading cause of reportable breaches.','GDPR Art. 32(1)(d); ICO Security Outcome 3; NCSC Vulnerability Management | ISO 27002 cl.8.8 (Management of technical vulnerabilities)','Critical','Monthly vulnerability scan reports; patch management records (critical ≤14 days, high ≤30 days); annual penetration test reports (independent); remediation tracking log.','Implement monthly vulnerability scanning. Define patch SLAs: critical ≤14 days, high ≤30 days, medium ≤90 days. Conduct annual independent penetration tests. Report remediation metrics to DPO monthly.','gdpr.S4Q7'),
  (4,'Security of Personal Data','ACCESS CONTROL & IDENTITY MANAGEMENT',8,'Is a formal joiners-movers-leavers (JML) process in place, with access provisioned, modified, and revoked promptly — leavers within 24 hours — per GDPR Art. 32 and ISO 27002 cl.5.18?','GDPR Art. 32 requires access controls proportionate to risk. Former employee accounts with continued access represent a significant and frequently exploited vulnerability. ISO 27002 cl.5.18 (Access rights) requires timely revocation as a specific control.','GDPR Art. 32; ICO Security Outcome 4 | ISO 27002 cl.5.18 (Access rights), cl.6.1 (Screening)','Critical','JML procedure integrated with HR; onboarding/offboarding checklists; access provisioning/de-provisioning logs; evidence of access removal within 24 hours for leavers; quarterly access recertification reports.','Integrate JML with HR to trigger automated IT notifications. Verify access removal within 24 hours for leavers. Conduct quarterly access recertification reviews.','gdpr.S4Q8'),
  (4,'Security of Personal Data','ACCESS CONTROL & IDENTITY MANAGEMENT',9,'Is RBAC implemented with least-privilege principles, and are access rights formally requested, approved, and documented, with a PAM solution for privileged accounts per ISO 27002 cl.8.2?','GDPR Art. 32 requires access limited to those who need it. ISO 27002 cl.8.2 (Privileged access rights) and cl.5.18 (Access rights) provide the control standards. Overly broad access rights amplify the impact of any breach or insider threat.','GDPR Art. 32; ICO Security Outcome 4 | ISO 27002 cl.8.2 (Privileged access rights), cl.5.18 (Access rights)','Critical','RBAC matrix aligned to job roles; access request and approval forms; system access reports confirming RBAC alignment; PAM solution for administrative accounts; quarterly access rights review records.','Develop and maintain an RBAC matrix. Require formal access requests with approvals. Implement a PAM solution for administrative accounts. Conduct quarterly access reviews.','gdpr.S4Q9'),
  (4,'Security of Personal Data','ACCESS CONTROL & IDENTITY MANAGEMENT',10,'Is MFA enforced for all remote access, privileged accounts, cloud platforms, and systems processing special category data per GDPR Art. 32 and ISO 27002 cl.8.5?','GDPR Art. 32 requires security proportionate to risk. MFA is a universally recognised critical control. ISO 27002 cl.8.5 (Secure authentication) specifically includes MFA as an authentication control. The ICO has cited MFA failures in enforcement decisions.','GDPR Art. 32; ICO Security Outcome 4; NCSC MFA guidance | ISO 27002 cl.8.5 (Secure authentication)','Critical','MFA policy; MFA configuration evidence (Azure AD Conditional Access, Okta, Duo, etc.); list of systems with MFA enforced; exceptions register with compensating controls; annual MFA coverage audit.','Enforce MFA on all remote access, cloud platforms, and sensitive data systems. Maintain an exceptions register. Review exceptions quarterly.','gdpr.S4Q10'),
  (4,'Security of Personal Data','ACCESS CONTROL & IDENTITY MANAGEMENT',11,'Is there a documented password/credential policy enforcing minimum length (14+ characters), complexity, prohibition on reuse, and account lockout, per GDPR Art. 32 and ISO 27002 cl.5.17?','GDPR Art. 32 requires appropriate technical measures. ISO 27002 cl.5.17 (Authentication information) provides the control standard for credential policies. Weak credentials are a leading cause of personal data breaches.','GDPR Art. 32; ICO Security Outcome 4; NCSC Password Guidance; NIST SP 800-63B | ISO 27002 cl.5.17 (Authentication information)','High','Password policy; Active Directory/IdP configuration confirming enforcement; account lockout configuration (max 10 attempts); prohibition on reuse of last 12 passwords; MFA deployment evidence.','Implement password policy per NCSC guidance (14+ character passphrase, lockout after 10 attempts, prohibition on reuse of last 12). Enforce via AD or IdP. Prioritise MFA.','gdpr.S4Q11'),
  (4,'Security of Personal Data','DATA LOSS PREVENTION & ENDPOINT SECURITY',12,'Is a DLP solution deployed to detect and prevent unauthorised transfer of personal data via email, web, cloud sync, or removable media per GDPR Art. 32 and ISO 27002 cl.8.12?','GDPR Art. 32 requires prevention of unauthorised disclosure. ISO 27002 cl.8.12 (Data leakage prevention) provides the control standard for DLP. DLP alerts can also provide early breach detection, supporting the 72-hour notification obligation.','GDPR Art. 32, 33; ICO Security Outcome 7 | ISO 27002 cl.8.12 (Data leakage prevention)','High','DLP solution configuration and policy rules; DLP alert and incident logs; monthly DLP incident report; policy refinement evidence.','Deploy enterprise DLP covering endpoint, email, and network channels. Define policies for personal data categories. Review alerts weekly. Report incidents monthly to DPO.','gdpr.S4Q12'),
  (4,'Security of Personal Data','DATA LOSS PREVENTION & ENDPOINT SECURITY',13,'Are removable media ports disabled or strictly controlled per GDPR Art. 32 and ISO 27002 cl.7.10, with exceptions subject to formal approval?','Removable media is a common vector for data loss and exfiltration. ISO 27002 cl.7.10 (Storage media) requires controls over removable media. Unencrypted personal data on lost USB drives constitutes a reportable breach.','GDPR Art. 32; ICO Security Outcome 7 | ISO 27002 cl.7.10 (Storage media)','High','Endpoint management configuration showing USB restriction; exceptions register with management and DPO approval; approved encrypted USB whitelist; removable media usage logs.','Block all removable media by default. Establish a formal exception process with DPO approval. Whitelist only encrypted USB devices. Log all approved usage.','gdpr.S4Q13'),
  (4,'Security of Personal Data','DATA LOSS PREVENTION & ENDPOINT SECURITY',14,'Are all laptops and mobile devices subject to full-disk encryption, MDM enrolment, and remote wipe per GDPR Art. 32(1)(a) and ISO 27002 cl.8.1?','Lost or stolen unencrypted devices are one of the most common reportable breach sources. ISO 27002 cl.8.1 (User endpoint devices) and GDPR Art. 32(1)(a) (encryption as an appropriate measure) set the standard. Remote wipe is essential for mobile device management.','GDPR Art. 32(1)(a); ICO Security Outcome 7; NCSC Device Security | ISO 27002 cl.8.1 (User endpoint devices), cl.8.24 (Use of cryptography)','Critical','MDM enrolment reports; full-disk encryption compliance reports (BitLocker/FileVault); remote wipe capability evidence; lost/stolen device response procedure; annual device audit.','Enrol all endpoints in MDM. Enforce full-disk encryption. Enable remote wipe. Define and test lost/stolen device response procedure annually.','gdpr.S4Q14'),
  (4,'Security of Personal Data','AUDIT LOGGING & MONITORING',15,'Are audit logs maintained for all access to and processing of personal data across all systems, retained for minimum 12 months, and protected from tampering per GDPR Art. 32(1)(d) and ISO 27002 cl.8.15?','GDPR Art. 32(1)(d) requires regular testing of security measures — which depends on audit logs. ISO 27002 cl.8.15 (Logging) and cl.8.17 (Clock synchronisation) provide the control standards. Tamperable logs have limited evidential value in breach investigations.','GDPR Art. 32(1)(d); DUAA 2025 s.84; ICO Security Outcome 6 | ISO 27002 cl.8.15 (Logging), cl.8.17 (Clock synchronisation)','High','SIEM/log management system; audit log retention policy (minimum 12 months); sample audit trails (user ID, action, timestamp, data accessed); tamper-evident log storage; NTP synchronisation configuration.','Enable and centralise audit logging in a SIEM. Capture: user ID, action type, timestamp (UTC), system, data category. Configure NTP. Retain logs for minimum 12 months. Protect from tampering.','gdpr.S4Q15'),
  (4,'Security of Personal Data','AUDIT LOGGING & MONITORING',16,'Are audit logs reviewed regularly for anomalous activity, with automated SIEM alerting configured for high-risk events per GDPR Art. 32(1)(d) and ISO 27002 cl.8.16?','Unreviewed logs provide no protection. ISO 27002 cl.8.16 (Monitoring activities) requires regular log review and automated alerting. GDPR Art. 32(1)(d) requires regular evaluation of security measure effectiveness. Automated alerting is critical for meeting the 72-hour breach notification obligation.','GDPR Art. 32(1)(d), 33; ICO Security Outcome 6 | ISO 27002 cl.8.16 (Monitoring activities)','High','SIEM use case/alert rule documentation; alert log with investigation records; security operations daily review evidence; escalation and resolution records; monthly anomaly metrics to DPO.','Configure SIEM alerting for: bulk downloads, off-hours access, privilege escalation, repeated failed authentications, special category data access. Assign daily analyst review. Document all investigations.','gdpr.S4Q16'),
  (4,'Security of Personal Data','SECURITY INCIDENT & BREACH MANAGEMENT',17,'Does the organisation have a documented, tested Security Incident and Personal Data Breach Response Plan covering the GDPR Art. 33 72-hour notification obligation and Art. 34 data subject notification, with ISO 27701 cl.6.13 breach management procedures?','GDPR Arts. 33–34 impose mandatory notification obligations. ISO 27701 cl.6.13 (PII breach management) and ISO 27002 cl.5.24–5.26 provide the operational framework for breach response. Failure to notify within 72 hours or late notification are among the most common enforcement outcomes.','GDPR Art. 33–34; DUAA 2025 s.84; EDPB Guidelines 01/2021 | ISO 27701 cl.6.13 (PII breach management); ISO 27002 cl.5.24–5.26 (Incident management)','Critical','Incident Response Plan with breach notification procedure; breach notification templates (to ICO and data subjects); breach register; annual tabletop exercise report; ICO notification records; DPO breach decision records.','Develop an IRP with a dedicated breach notification procedure per ISO 27701 cl.6.13. Define the 72-hour ICO notification SLA and data subject notification triggers. Test annually via tabletop. Review after every actual breach.','gdpr.S4Q17'),
  (4,'Security of Personal Data','SECURITY INCIDENT & BREACH MANAGEMENT',18,'Is a breach/incident register maintained per GDPR Art. 33(5) and ISO 27701 cl.6.13.1–6.13.2, with root-cause analysis conducted for every confirmed breach and metrics reported to management quarterly?','GDPR Art. 33(5) requires documentation of all breaches. ISO 27701 cl.6.13.1 (Responsibilities and procedures for PII breach management) and cl.6.13.2 require structured breach documentation, investigation, and corrective action. A comprehensive register is both a compliance requirement and an operational improvement tool.','GDPR Art. 33(5), 5(2); EDPB Guidelines 01/2021 | ISO 27701 cl.6.13.1 (PII breach responsibilities & procedures), cl.6.13.2 (PII breach assessment)','Critical','Breach/incident register (date, nature, data categories, number of data subjects, containment, notifications, root cause, lessons learned); root cause analysis reports; quarterly breach metrics to management; remediation tracked to closure.','Maintain a centralised breach register per ISO 27701 cl.6.13.1. Report to DPO within 24 hours. Conduct root cause analysis for every confirmed breach. Report metrics quarterly to management.','gdpr.S4Q18'),
  (5,'Data Subject Rights & Requests','GOVERNANCE & DESIGNATED RESPONSIBILITY',1,'Has the organisation designated responsibility for data subject rights to the DPO (or named deputy), are contact details published per ISO 27701 cl.7.3.1, and is there a dedicated intake channel for rights requests?','GDPR Art. 12 requires controllers to facilitate rights. Arts. 13–14 require DPO contact details in privacy notices. ISO 27701 cl.7.3.1 (Obligations to PII principals) requires organisations to establish procedures for fulfilling PII principal rights. DUAA 2025 s.46–55 enhances portability rights requiring clear intake processes.','GDPR Art. 12–14, 37(7); DUAA 2025 s.46–55 | ISO 27701 cl.7.3.1 (Obligations to PII principals), cl.5.3.2 (Roles & responsibilities)','Critical','DPO contact details on website, in privacy notices, and in all data subject communications; dedicated rights intake channel (email or web form); deputy DPO designation; DPO appointment letter.','Publish DPO contact details on website and in all privacy notices per ISO 27701 cl.7.3.1. Create a dedicated intake channel. Designate a deputy DPO for absence cover.','gdpr.S5Q1'),
  (5,'Data Subject Rights & Requests','RIGHT OF ACCESS (SUBJECT ACCESS REQUESTS)',2,'Does the organisation have a documented SAR procedure per GDPR Art. 15 and ISO 27701 cl.7.3.2–7.3.6, with responses within one month and extension procedures documented?','GDPR Art. 15 gives data subjects the right of access. Art. 12 requires responses within one month. ISO 27701 cl.7.3.2 (Providing access to PII) and cl.7.3.6 (Providing mechanism to obtain PII) operationalise the SAR response process. The DUAA 2025 enhances portability rights that may accompany SARs.','GDPR Art. 12, 15; DUAA 2025 s.46–55; EDPB Guidelines 01/2022 | ISO 27701 cl.7.3.2 (Providing access to PII), cl.7.3.6 (Mechanism to obtain PII)','Critical','SAR procedure document; SAR tracking register (date, due date, extension decision, status, outcome); response templates; identity verification checklist; evidence of responses within one month; extension notification evidence.','Develop a SAR procedure per ISO 27701 cl.7.3.2. Cover: intake, identity verification, acknowledgement within 5 days, search across all systems, DPO approval, dispatch within one month. Set Day-20 and Day-27 reminder alerts.','gdpr.S5Q2'),
  (5,'Data Subject Rights & Requests','RIGHT OF ACCESS (SUBJECT ACCESS REQUESTS)',3,'Is identity verification proportionate, not creating unnecessary barriers per GDPR Art. 12(2)–(6) and ISO 27701 cl.7.3.6?','GDPR Art. 12(6) allows additional information requests where identity is reasonably doubtful. Art. 12(2) requires procedures to be ''easily accessible''. ISO 27701 cl.7.3.6 requires a mechanism to obtain PII that is proportionate. Excessive verification is itself a breach.','GDPR Art. 12(2), 12(6); EDPB Guidelines 01/2022 | ISO 27701 cl.7.3.6 (Providing mechanism to obtain PII)','High','Identity verification procedure with proportionality assessment; verification checklist scaled to data sensitivity; log of verification steps per SAR; evidence of no excessive verification for low-risk requests.','Define a proportionate identity verification process. For low-risk requests, name and email may suffice. For high-risk, government-issued ID may be required. Document the proportionality rationale. Train all SAR handlers.','gdpr.S5Q3'),
  (5,'Data Subject Rights & Requests','RIGHT TO RECTIFICATION & ERASURE',4,'Does the organisation have a documented rectification procedure per GDPR Art. 16 and ISO 27701 cl.7.3.4 (Correcting or erasing PII), with corrections actioned across all systems within one month and third-party recipients notified per Art. 19?','GDPR Art. 16 gives the right to rectification. Art. 19 requires notification to all recipients of corrected data. ISO 27701 cl.7.3.4 provides the operational procedure for correcting or erasing PII. Failure to correct and notify recipients breaches both Art. 16 and the accuracy principle.','GDPR Art. 16, 19, 5(1)(d); EDPB Guidelines 01/2022 | ISO 27701 cl.7.3.4 (Correcting or erasing PII)','High','Rectification request procedure; request log; evidence of corrections in all systems; notifications to third-party recipients; confirmation to data subject.','Develop a rectification procedure per ISO 27701 cl.7.3.4. Update all systems within one month. Notify third-party recipients per Art. 19. Log all requests and outcomes.','gdpr.S5Q4'),
  (5,'Data Subject Rights & Requests','RIGHT TO RECTIFICATION & ERASURE',5,'Does the organisation have an erasure procedure per GDPR Art. 17 and ISO 27701 cl.7.3.4 and cl.7.4.8, assessing Art. 17(3) grounds, actioning deletion across all systems including processors within one month?','GDPR Art. 17 gives the right to erasure (''right to be forgotten''). ISO 27701 cl.7.3.4 (Correcting or erasing PII) and cl.7.4.8 (Disposal of PII) operationalise erasure. Art. 17(3) provides grounds to refuse. Art. 19 requires processor notification. Blanket refusals or failure to action within one month breach Art. 17.','GDPR Art. 17, 19; DUAA 2025 s.46–55; EDPB Guidelines 01/2022 | ISO 27701 cl.7.3.4 (Correcting or erasing PII), cl.7.4.8 (Disposal of PII)','High','Erasure request procedure; request log; Art. 17(3) grounds assessment records; deletion confirmation to data subject; evidence of deletion from all systems including processors; exceptions log where Art. 17(3) applies.','Develop an erasure procedure per ISO 27701 cl.7.3.4 and cl.7.4.8. Assess Art. 17(3) grounds. Action deletion across all systems — CRM, HR, ERP, archives, processors — within one month. Notify processors. Provide written confirmation.','gdpr.S5Q5'),
  (5,'Data Subject Rights & Requests','RIGHT TO RESTRICTION, PORTABILITY & OBJECTION',6,'Does the organisation have procedures for restriction of processing (Art. 18) and data portability (Art. 20 / DUAA 2025 s.46–55), including machine-readable export capability and API delivery per ISO 27701 obligations to PII principals?','GDPR Art. 18 gives the right to restrict processing. Art. 20 gives the right to data portability. The DUAA 2025 significantly enhances portability rights through smart data schemes, requiring data to be shared with designated third parties in specified formats — a new operational capability.','GDPR Art. 18, 20; DUAA 2025 s.46–55; EDPB Guidelines 05/2022 | ISO 27701 cl.7.3 (Obligations to PII principals – general)','High','Restriction request procedure; portability request procedure; restricted data flagging evidence in all systems; machine-readable data export capability (JSON/CSV); API documentation; DUAA 2025 smart data compliance assessment.','Develop restriction and portability procedures. Implement machine-readable export capability. Assess DUAA 2025 smart data obligations for your sector. Respond to portability requests within one month.','gdpr.S5Q6'),
  (5,'Data Subject Rights & Requests','RIGHT TO RESTRICTION, PORTABILITY & OBJECTION',7,'Does the organisation have a procedure for objections to processing per GDPR Art. 21, with automatic suspension of processing pending DPO review, and immediate cessation for direct marketing objections?','GDPR Art. 21 gives the right to object. For direct marketing objections, cessation is mandatory with no balancing test. ISO 27701 cl.7.3.5 (Providing mechanism to object to PII processing) requires a functioning objection mechanism. Failure to process objections is a common enforcement issue.','GDPR Art. 21; EDPB Guidelines 01/2022 | ISO 27701 cl.7.3.5 (Providing mechanism to object to PII processing)','High','Objection handling procedure; objection request log; evidence of processing suspension during review; DPO decision record with reasons; communication to data subject within one month.','Develop an objection procedure per ISO 27701 cl.7.3.5. For direct marketing objections, cease immediately. For other objections, suspend processing pending DPO review. Communicate decision within one month.','gdpr.S5Q7'),
  (5,'Data Subject Rights & Requests','RIGHT TO COMPLAIN & AUTOMATED DECISION-MAKING',8,'Are data subjects informed of their right to lodge a complaint with the ICO/supervisory authority per GDPR Arts. 13–14 and ISO 27701 cl.7.3.1, and is there an internal complaints procedure for first-line resolution?','GDPR Arts. 13–14 require privacy notices to include the right to complain to the supervisory authority. ISO 27701 cl.7.3.1 requires obligations to PII principals to be established, including complaint handling. An effective internal procedure reduces ICO referrals.','GDPR Art. 13(2)(d), 14(2)(e), 77 | ISO 27701 cl.7.3.1 (Obligations to PII principals), cl.7.3.9 (Automated decision-making)','High','Privacy notices referencing right to complain to ICO (ico.org.uk); internal complaints procedure; complaint register; evidence of complaints resolved within 20 business days.','Include ICO complaint right in all privacy notices. Establish an internal procedure with 20 business day target. Maintain a complaint register.','gdpr.S5Q8'),
  (5,'Data Subject Rights & Requests','RIGHT TO COMPLAIN & AUTOMATED DECISION-MAKING',9,'Where automated decision-making including profiling produces legal or significant effects, has this been identified, disclosed, and are Art. 22 and ISO 27701 cl.7.3.9 safeguards implemented?','GDPR Art. 22 restricts purely automated significant decisions. ISO 27701 cl.7.3.9 (Automated decision-making) requires disclosure of automated processing and a mechanism for human review. The DUAA 2025 requires transparency around automated processing in intermediary services.','GDPR Art. 22, 13(2)(f), 14(2)(g); DUAA 2025 s.68; EDPB Guidelines 03/2017 | ISO 27701 cl.7.3.9 (Automated decision-making)','High','Inventory of automated decision-making processes; privacy notice disclosures; DPIA for high-risk automated decisions; human review procedure; profiling opt-out mechanism.','Identify all automated decision-making. Disclose in privacy notices per ISO 27701 cl.7.3.9. Establish human review process. Conduct DPIAs for high-risk automated decisions. Implement profiling opt-out.','gdpr.S5Q9'),
  (5,'Data Subject Rights & Requests','STAFF AWARENESS & REQUEST TRACKING',10,'Are front-line staff trained to recognise data subject rights requests regardless of channel, and to route them to the DPO within one business day, per GDPR Art. 12 and ISO 27701 cl.7.4 (Awareness)?','GDPR Art. 12 requires rights to be ''easily accessible''. Data subjects may exercise rights through any channel. The one-month clock starts on receipt — not when it reaches the DPO. ISO 27701 cl.7.4 (Awareness) requires staff to be aware of PII principal rights and their role in supporting them.','GDPR Art. 12(2), 12(3); EDPB Guidelines 01/2022 | ISO 27701 cl.7.4 (Awareness), cl.7.3 (Obligations to PII principals)','High','Staff training records on data subject rights; call/email routing scripts; SAR routing procedure; evidence of requests correctly identified and routed within one business day.','Include rights recognition and routing in all GDPR/ISO 27701 training. Provide scripts for all channels. Require escalation to DPO within one business day.','gdpr.S5Q10'),
  (5,'Data Subject Rights & Requests','STAFF AWARENESS & REQUEST TRACKING',11,'Are all data subject rights requests logged in a centralised tracking system with automated deadline reminders, and are metrics reported to the DPO monthly as part of ISO 27701 PIMS monitoring?','GDPR Art. 12 requires responses within one month. A centralised tracking system is essential for deadline management and accountability. ISO 27701 cl.9.1 (Monitoring, measurement, analysis and evaluation) requires the effectiveness of rights request management to be monitored as part of PIMS performance evaluation.','GDPR Art. 12(3), 5(2) | ISO 27701 cl.9.1 (Monitoring, measurement, analysis & evaluation)','High','SAR tracking register or ticketing system; Day-20 and Day-27 automated reminder evidence; monthly SAR metric report to DPO; escalation log for complex requests.','Implement a centralised SAR tracking system. Configure Day-20 and Day-27 reminders. Report SAR volumes, completion rates, and average response times to DPO monthly as part of ISO 27701 cl.9.1 PIMS monitoring.','gdpr.S5Q11'),
  (6,'Direct Marketing','CONSENT MANAGEMENT',1,'Does the organisation obtain freely given, specific, informed, and unambiguous opt-in consent per GDPR Art. 6(1)(a)/Art. 7, PECR Reg. 22, and ISO 27701 cl.7.2.3 before conducting electronic direct marketing, with consent granular per channel and purpose?','GDPR Art. 7 and PECR Reg. 22 require opt-in consent for electronic direct marketing. ISO 27701 cl.7.2.3 (When and how consent is obtained) operationalises consent capture at a system level. Pre-ticked boxes, bundled consent, and consent buried in T&Cs are all non-compliant and a major ICO enforcement focus.','GDPR Art. 6(1)(a), 7; PECR Reg. 22 (UK); ePrivacy Directive Art. 13; DUAA 2025 s.68 | ISO 27701 cl.7.2.3 (When & how consent is obtained), cl.7.3.3 (Fulfilling obligations to PII principals)','Critical','Consent management system records (timestamp, wording version, channel, purpose per data subject); opt-in forms with no pre-ticked boxes; consent audit report.','Implement opt-in consent per ISO 27701 cl.7.2.3 for every electronic marketing channel. Ensure consent is granular, unambiguous, and fully recorded. Audit all mechanisms. Remove pre-ticked boxes and bundled consent.','gdpr.S6Q1'),
  (6,'Direct Marketing','CONSENT MANAGEMENT',2,'Is consent for direct marketing captured separately from consent for service delivery, with no bundling per GDPR Art. 7(2) and ISO 27701 cl.7.2.3?','GDPR Art. 7(2) and EDPB Guidelines 05/2020 require marketing consent to be clearly distinguishable from other consent. ISO 27701 cl.7.2.3 requires consent to be specific to the processing activity. Bundled consent is a common enforcement target.','GDPR Art. 7(2); EDPB Guidelines 05/2020; PECR Reg. 22 | ISO 27701 cl.7.2.3 (When & how consent is obtained)','Critical','Consent form design showing separate checkboxes for marketing vs. service purposes; CRM with distinct consent flags per purpose; consent wording review log confirming no bundling.','Audit all consent collection mechanisms. Ensure marketing consent is a separate, clearly distinguishable, optional tick-box. Update web forms, paper forms, app onboarding, and call scripts.','gdpr.S6Q2'),
  (6,'Direct Marketing','CONSENT MANAGEMENT',3,'Are consent records retained for 3 years post-relationship as evidence of lawful marketing per GDPR Art. 5(2) and ISO 27701 cl.7.2.3, and preserved even after opt-out?','GDPR Art. 5(2) accountability requires the ability to demonstrate valid consent. ISO 27701 cl.7.2.3 requires consent records to be maintained. Records must be preserved even after opt-out as evidence of prior lawful processing.','GDPR Art. 7(1), 5(2); PECR Reg. 22 | ISO 27701 cl.7.2.3 (When & how consent is obtained), cl.7.4.7 (Minimum necessary PII – retention)','High','Consent record retention policy (3 years post-relationship); CRM export showing consent date, wording version, channel; evidence of historical consent records preserved after opt-out.','Configure the CRM or consent management platform to retain records for relationship duration plus 3 years. Document in the Data Retention Policy. Preserve records even after opt-out.','gdpr.S6Q3'),
  (6,'Direct Marketing','OPT-OUT & CONSENT WITHDRAWAL',4,'Is a simple, cost-free opt-out/unsubscribe mechanism included in every direct marketing communication, and is withdrawal actioned within 5 business days per GDPR Art. 7(3), PECR Reg. 22(3)(b), and ISO 27701 cl.7.3.5?','PECR Reg. 22(3)(b) requires an opt-out opportunity in every electronic marketing communication. GDPR Art. 7(3) requires withdrawal to be as easy as giving consent. ISO 27701 cl.7.3.5 (Providing mechanism to modify or withdraw consent) operationalises the withdrawal process.','GDPR Art. 7(3); PECR Reg. 22(3)(b); ePrivacy Directive Art. 13(2) | ISO 27701 cl.7.3.5 (Providing mechanism to modify or withdraw consent)','Critical','Sample email, SMS, and digital communications showing one-click unsubscribe or STOP instruction; opt-out processing log with action dates; suppression list; SLA evidence (5 business days).','Include one-click unsubscribe (email) or STOP (SMS) in every communication. Define 5 business day SLA per ISO 27701 cl.7.3.5. Configure CRM to automatically suppress opted-out data subjects. Conduct monthly suppression audits.','gdpr.S6Q4'),
  (6,'Direct Marketing','OPT-OUT & CONSENT WITHDRAWAL',5,'Is the central suppression/do-not-contact list scrubbed against all marketing lists before every campaign send, across all channels simultaneously, per GDPR Art. 7(3) and ISO 27701 cl.7.3.5?','A central suppression list applied consistently across all channels is the control mechanism ensuring opted-out data subjects are not re-contacted. ISO 27701 cl.7.3.5 requires the withdrawal mechanism to be consistently effective. Failure to scrub before every send is a PECR breach.','GDPR Art. 7(3); PECR Reg. 22 | ISO 27701 cl.7.3.5 (Providing mechanism to modify or withdraw consent)','Critical','Suppression list management procedure; pre-campaign scrubbing evidence (list counts before and after suppression); CRM suppression report; cross-channel suppression evidence.','Maintain a central suppression list covering all channels. Require mandatory scrubbing before every campaign send per ISO 27701 cl.7.3.5. Confirm cross-channel suppression simultaneously. Audit monthly.','gdpr.S6Q5'),
  (6,'Direct Marketing','THIRD-PARTY & OUTSOURCED MARKETING',6,'Where marketing is outsourced to agencies or platforms, is a GDPR Art. 28 / ISO 27701 cl.6.12-compliant DPA in place with each, and has their compliance been assessed?','GDPR Art. 28 requires a written DPA with every processor. ISO 27701 cl.6.12 (Supplier relationships) and cl.6.12.1 require processor governance and ongoing monitoring. Marketing agencies, email platforms, and ad networks are processors. Using a non-compliant processor exposes the controller to liability.','GDPR Art. 28; DUAA 2025 s.66–83 | ISO 27701 cl.6.12.1 (Supplier relationships – information security), cl.8.5 (Processor obligations)','Critical','Signed DPAs with all marketing processors; compliance assessment questionnaire; ISO 27001/SOC 2 certification evidence; right-to-audit clause in DPA; annual review records.','Identify all marketing processors. Execute GDPR Art. 28 / ISO 27701 cl.6.12-compliant DPAs. Conduct annual assessments. Exercise audit rights for high-risk processors at least every two years.','gdpr.S6Q6'),
  (6,'Direct Marketing','THIRD-PARTY & OUTSOURCED MARKETING',7,'If the organisation uses third-party marketing lists, has robust due diligence confirmed that valid, specific consent exists for data subjects to be contacted by this specific organisation, per GDPR Art. 6(1)(a) and ISO 27701 cl.7.2.3?','Consent given to a list provider is not consent to be contacted by a purchaser. GDPR Art. 6(1)(a) requires consent to be specific to the controller. ISO 27701 cl.7.2.3 requires the lawful basis for processing to be documented. Using purchased lists without specific consent is a major PECR/GDPR enforcement risk.','GDPR Art. 6(1)(a), 7; PECR Reg. 22; ICO Direct Marketing guidance | ISO 27701 cl.7.2.3 (When & how consent is obtained)','Critical','List provider contracts with consent warranty naming the organisation as recipient; sample consent evidence; due diligence checklist; re-consent campaign records where provenance is uncertain.','Require written consent warranties from list providers specifying your organisation as named recipient. Where provenance is uncertain, conduct a re-consent campaign. Cease use of any list where valid, specific consent cannot be demonstrated.','gdpr.S6Q7'),
  (6,'Direct Marketing','THIRD-PARTY & OUTSOURCED MARKETING',8,'Does the organisation prohibit sharing or selling customer personal data to third parties for their own marketing without explicit, separately obtained consent, per GDPR Art. 6(1)(a) and ISO 27701 cl.7.2.7?','Sharing or selling personal data for third-party marketing requires a separate, explicit lawful basis. ISO 27701 cl.7.2.7 (Disclosures to third parties) requires documented authorisation for all third-party disclosures. Unauthorised data sharing is a serious GDPR breach and enforcement priority.','GDPR Art. 6(1)(a), 44; PECR Reg. 22; ICO Data Sharing Code | ISO 27701 cl.7.2.7 (Disclosures to third parties)','Critical','Data sharing policy prohibiting unauthorised marketing data sharing; partner contracts with data sharing restrictions; consent records for any approved sharing; annual data sharing audit log.','Implement a data sharing policy per ISO 27701 cl.7.2.7 prohibiting sale/transfer for third-party marketing without explicit consent. Include restrictions in partner contracts. Audit annually.','gdpr.S6Q8'),
  (6,'Direct Marketing','ELECTRONIC MARKETING COMPLIANCE',9,'Do all electronic marketing communications identify the organisation by full legal name, include a physical/postal address, and provide a valid contact address per PECR Reg. 22(3)(a) and ISO 27701 cl.7.3.2 (transparency obligations)?','PECR Reg. 22(3)(a) requires sender identification. ISO 27701 cl.7.3.2 (Providing privacy notices) requires transparency in all communications. Failure to identify the sender undermines the right to object and is a direct PECR breach.','PECR Reg. 22(3)(a); CAP Code; GDPR Art. 5(1)(a) | ISO 27701 cl.7.3.2 (Providing privacy notices)','High','Sample marketing emails, SMSs, and digital communications; marketing template compliance review log; CAP Code compliance checklist.','Review all templates. Ensure each includes: full legal name, valid physical/postal address, and valid contact. Update non-compliant templates. Conduct quarterly template reviews.','gdpr.S6Q9'),
  (6,'Direct Marketing','ELECTRONIC MARKETING COMPLIANCE',10,'Is the organisation''s use of electronic marketing channels documented in a Direct Marketing Policy per GDPR Art. 5(2), ISO 27701 cl.5.2 (PIMS policy), and PECR, with DPO oversight assigned?','A documented Direct Marketing Policy demonstrates GDPR Art. 5(2) accountability. ISO 27701 cl.5.2 (PIMS policy and objectives) requires PII-related objectives to be documented. The DUAA 2025 requires policies to address smart data marketing obligations.','GDPR Art. 5(2), 24; PECR; DUAA 2025 s.68 | ISO 27701 cl.5.2 (PIMS policy & objectives)','High','Direct Marketing Policy (board-approved, version-controlled); channel-specific compliance guidelines; role assignments (marketing manager, DPO); training records.','Develop a Direct Marketing Policy per ISO 27701 cl.5.2. Cover: permitted channels, consent requirements, opt-out SLAs, prohibited practices, DUAA 2025 obligations, DPO oversight. Board-approve. Train all marketing staff annually.','gdpr.S6Q10'),
  (6,'Direct Marketing','PROFILING, COOKIES & TARGETED MARKETING',11,'Where profiling or tracking technologies (cookies, pixels, fingerprinting) are used for marketing, is this disclosed in the privacy/cookie notice and are PECR Reg. 6 / ISO 27701 cl.7.3.9 compliant consent mechanisms in place?','PECR Reg. 6 requires prior consent for non-essential cookies. GDPR Art. 22 regulates automated profiling with significant effects. ISO 27701 cl.7.3.9 (Automated decision-making) requires disclosure and safeguards for profiling. Bundled cookie consent is non-compliant.','GDPR Art. 22; PECR Reg. 6; ePrivacy Directive Art. 5(3); ICO Cookie guidance | ISO 27701 cl.7.3.9 (Automated decision-making), cl.7.3.2 (Privacy notices)','High','Privacy notice and cookie policy disclosing profiling and targeting; PECR-compliant CMP with prior consent for non-essential cookies; profiling opt-out mechanism; DPIA for high-risk profiling.','Implement a PECR-compliant CMP per ISO 27701 cl.7.3.9 for all non-essential cookies. Disclose profiling in privacy notice. Provide profiling opt-out. Conduct DPIA for high-risk profiling.','gdpr.S6Q11'),
  (6,'Direct Marketing','PROFILING, COOKIES & TARGETED MARKETING',12,'Does the organisation maintain campaign records (channel, audience, consent basis, suppression, opt-out rate) for minimum 3 years to demonstrate GDPR Art. 5(2) accountability and ISO 27701 PIMS documentation requirements?','GDPR Art. 5(2) accountability requires the ability to demonstrate compliance. ISO 27701 cl.7.2.1 (RoPA and documentation) and cl.9.1 (Monitoring) require campaign records to be maintained as evidence of lawful marketing. ICO investigations routinely request campaign records.','GDPR Art. 5(2), 30; PECR | ISO 27701 cl.7.2.1 (PII inventory & mapping), cl.9.1 (Monitoring, measurement, analysis & evaluation)','Medium','Campaign records log (date, channel, audience size, consent basis, suppression applied, opt-out count, compliance sign-off); 3-year records retention; quarterly marketing compliance report to DPO.','Implement a campaign records register per ISO 27701 cl.9.1 capturing all required fields. Retain for minimum 3 years. Report marketing compliance metrics to DPO quarterly as part of PIMS monitoring.','gdpr.S6Q12')
) AS x(section_id, section_name, subsection, qn, question, why, ref, risk, evidence, remediation, uid)
ON CONFLICT (uid) DO NOTHING;

COMMIT;
